(function () {
  'use strict';
  window.QUESTION_BANK = Object.assign(window.QUESTION_BANK || {}, {"punctuation-quotation-marks":{"title":"Quotation Marks","topic":"Punctuation","questions":[{"id":"punctuation-quotation-marks-q0001","version":4,"contentHash":"sha256:3b4739f38ad9dcc37cc50338b2c7e59879a812a1107e0a00ba3e92616e00c061","question":"Which sentence uses quotation marks correctly?","choices":["'I'm hungry,' said Mom.","\"I'm hungry,\" said Mom.","'I'm hungry', said Mom.","\"I'm hungry\" said Mom."],"correct":1,"explanation":{"correct":"Answer: \"I'm hungry,\" said Mom. When a quotation ends a sentence, the comma should go inside the closing quotation mark, and the first word inside the quote must be capitalized.","incorrect":[{"choice":"'I'm hungry,' said Mom.","category":"incorrect quotation mark","reason":"This choice uses single quotation marks instead of the standard double quotation marks required for dialogue in most English writing."},"",{"choice":"'I'm hungry', said Mom.","category":"misplaced punctuation","reason":"This choice uses single quotation marks and places the comma outside of them. Remember to use double quotes and tuck your comma inside."},{"choice":"\"I'm hungry\" said Mom.","category":"missing comma","reason":"Even though this choice uses double quotes, it is missing a comma to separate the spoken words from the speaker. You need a comma before the closing quote."}]},"studyAid":{"definition":"Use double quotation marks to show someone is speaking, and place commas and periods inside the closing quotation mark.","example":"\"Hello,\" said Sam. / The teacher asked, \"Is everyone ready?\"","strategyClue":"Check three things: Are double quotes used? Is there a comma separating the words from the speaker? Is that comma tucked safely inside the closing quotation mark?","link":"https://www.grammar-monster.com/punctuation/using_quotation_marks.htm","linkText":"Grammar Monster - Quotation Marks"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sequence":1,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-quotation-marks-q0002","version":3,"contentHash":"sha256:081c76b38de885917b1630e80c9bd62b7b1196c2e1f30a864eeebc3da5877df5","question":"Where do quotation marks go in this sentence: Maya said she loved the book.","choices":["Maya said, 'she loved the book.'","Maya said, 'She loved the book.'","Maya said she 'loved the book.'","Maya said, she loved the book."],"correct":1,"explanation":{"correct":"Answer: Maya said, 'She loved the book.' Quotation marks are used to set off the exact words someone says. In this case, we place a comma after the reporting verb 'said' and enclose the spoken words in quotation marks starting with a capital letter.","incorrect":[{"choice":"Maya said, 'she loved the book.'","category":"capitalization error","reason":"When a quotation acts as a complete sentence or begins after a comma, the first word inside the quotation marks should always start with a capital letter."},"",{"choice":"Maya said she 'loved the book.'","category":"partial quotation error","reason":"This style puts only part of the phrase in quotes. Since the speaker is stating the entire thought, the quotation marks should encompass the full sentence beginning after the comma."},{"choice":"Maya said, she loved the book.","category":"missing quotation marks","reason":"Without quotation marks, the reader cannot tell that 'she loved the book' is the specific thing Maya said. Marks are required to frame dialogue or direct speech."}]},"studyAid":{"definition":"Quotation marks show the exact words a person says, and they are usually introduced by a comma after the verb that tells us who is speaking.","example":"He said, 'I am hungry.' / She shouted, 'Watch out!'","strategyClue":"Identify the exact words being spoken. Place a comma before the first mark, and ensure the very first word inside the marks begins with an uppercase letter.","link":"https://www.grammar-monster.com/punctuation/using_quotation_marks.htm","linkText":"Grammar Monster - Quotation Marks"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sequence":2,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-quotation-marks-q0003","version":4,"contentHash":"sha256:2bfa4ae1ccdfc34853d6e930a96e557a7a11f8c7ab082f5d5f6b13a496926e0c","question":"Which sentence punctuates the question inside quotes correctly?","choices":["Maya asked, \"Are you leaving?\"","Maya asked, \"Are you leaving\"?","Maya asked \"Are you leaving?\"","Maya asked, \"are you leaving?\""],"correct":0,"explanation":{"correct":"Answer: Maya asked, \"Are you leaving?\". When a quoted sentence is a question, the question mark goes inside the closing quotation mark. Additionally, the first word of a direct quote should be capitalized.","incorrect":["",{"choice":"Maya asked, \"Are you leaving\"?","category":"misplaced terminal punctuation","reason":"The question mark belongs inside the quotation marks because the quoted speech itself is a question. Placing it outside incorrectly suggests the sentence as a whole is the question, rather than the quote."},{"choice":"Maya asked \"Are you leaving?\"","category":"missing comma","reason":"When introducing a direct quote with a verb like 'asked', you must place a comma before the opening quotation mark to separate the speaker from their words."},{"choice":"Maya asked, \"are you leaving?\"","category":"capitalization error","reason":"The first word of a direct quote must always be capitalized, even if it appears in the middle of your sentence."}]},"studyAid":{"definition":"Direct quotes represent the exact words spoken. They require a comma before the start of the quote, a capital letter to begin the quote, and end-punctuation inside the quotation marks.","example":"He said, \"Hello!\" / She asked, \"Where are we going?\" / \"I am tired,\" said Sam.","strategyClue":"Check your sentence in three steps: look for the introductory comma, verify that the first word of the quote starts with a capital letter, and ensure the punctuation mark for the quote's meaning is inside the closing marks.","link":"https://www.grammar-monster.com/punctuation/using_quotation_marks.htm","linkText":"Grammar Monster - Quotation Marks"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sequence":3,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-quotation-marks-q0004","version":6,"contentHash":"sha256:8aafcaa1b05ba1cdb077519bc33b892b80d26ba02159bc00478c05e2efdeafc2","question":"Which is correct when splitting a quote with a dialogue tag?","choices":["'I don't know,' she said 'what to do.'","\"I don't know,\" she said. \"What to do.\"","\"I don't know,\" she said, \"what to do.\"","\"I don't know\" she said, \"what to do.\""],"correct":2,"explanation":{"correct":"Answer: \"I don't know,\" she said, \"what to do.\" When you interrupt a sentence with a dialogue tag, you place a comma inside the first set of quotation marks and another comma after the dialogue tag before opening the second set of quotes.","incorrect":[{"choice":"'I don't know,' she said 'what to do.'","category":"missing comma and quotation","reason":"This choice uses single quotes instead of double quotes for dialogue and misses the essential comma after the word 'said' to separate the speaker from the rest of the quote."},{"choice":"\"I don't know,\" she said. \"What to do.\"","category":"incorrect sentence fragment","reason":"Using a period after 'said' creates a full sentence, making the second part ('What to do.') a sentence fragment. Since the original sentence is one thought, you should use commas."},"",{"choice":"\"I don't know\" she said, \"what to do.\"","category":"missing punctuation mark","reason":"You must include a comma inside the closing quotation mark of the first part of the quote to properly separate the speech from the speaker."}]},"studyAid":{"definition":"When a dialogue tag splits a single spoken sentence, use a comma at the end of the first part inside the quotation marks and another comma after the tag.","example":"\"It is raining,\" she noted, \"so take an umbrella.\" / \"I am tired,\" he whispered, \"but I will finish.\"","strategyClue":"Check if the dialogue tag is breaking one continuous sentence in half. If the same person is still speaking after the tag, look for commas that link the two parts of the sentence together.","link":"https://www.grammar-monster.com/punctuation/using_quotation_marks.htm","linkText":"Grammar Monster - Quotation Marks"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sequence":4,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-quotation-marks-q0005","version":4,"contentHash":"sha256:c0c25784fa7344fac7e2b9400dd5eb06af33ce79429d315182c8a0366a6e280b","question":"Which sentence uses single quotation marks correctly?","choices":["She said, 'I love the word 'serendipity.''","She said, 'I love the word \"serendipity.\"'","She said, 'I love the word 'serendipity'.'","She said, 'I love the word \"serendipity\".'"],"correct":1,"explanation":{"correct":"Answer: She said, 'I love the word \"serendipity.\"'. When a quotation includes another word that is already being quoted, use double quotation marks for the inner phrase and single quotation marks for the outer dialogue.","incorrect":[{"choice":"She said, 'I love the word 'serendipity.''","category":"nested quote error","reason":"Using single quotation marks for both layers is confusing. When you have a quote inside a quote, use different marks to show where the inner word begins and ends."},"",{"choice":"She said, 'I love the word 'serendipity'.'","category":"incorrect punctuation order","reason":"The punctuation inside the inner quote needs to follow standard rules, and the nesting must be clearly separated by changing from single to double quotation marks."},{"choice":"She said, 'I love the word \"serendipity\".'","category":"misplaced terminal punctuation","reason":"In American English, the period belongs inside the quotation marks at the end of the sentence. Your choice places the period outside, which breaks the standard rule for closing quotes."}]},"studyAid":{"definition":"When you need to put a quote inside another quote, use single quotation marks for the outside layer and double quotation marks for the inside layer.","example":"He shouted, \"Watch out!\" the teacher said. -> The teacher said, \"He shouted, 'Watch out!'\"","strategyClue":"Look at the nested word. If the main sentence is already wrapped in single quotes, check that the special word inside is wrapped in double quotes, and ensure the period is placed inside the final closing mark.","link":"https://www.grammar-monster.com/punctuation/using_quotation_marks.htm","linkText":"Grammar Monster - Quotation Marks"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sequence":5,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-quotation-marks-q0006","version":4,"contentHash":"sha256:c56237a003cedf132ad253d0c63ed4d713bbe4485f187b5ae02bd69f6d23b353","question":"Which sentence correctly uses quotation marks for a title?","choices":["I read the chapter The Big Storm in my book.","I read the chapter \"The Big Storm in my book.\"","I read the chapter \"The Big Storm\" in my book.","I read the chapter *The Big Storm* in my book."],"correct":2,"explanation":{"correct":"Answer: I read the chapter \"The Big Storm\" in my book. Titles of chapters, short stories, or poems should be enclosed in quotation marks, while the surrounding sentence remains outside the marks.","incorrect":[{"choice":"I read the chapter The Big Storm in my book.","category":"missing punctuation","reason":"Titles of short works like chapters need special marks to show where the title begins and ends. Without quotation marks, it is hard to tell which words are part of the title."},{"choice":"I read the chapter \"The Big Storm in my book.\"","category":"misplaced closing quotation","reason":"The quotation marks should only surround the title of the chapter. Including the rest of the sentence inside the marks incorrectly suggests that the whole sentence is the title."},"",{"choice":"I read the chapter *The Big Storm* in my book.","category":"incorrect punctuation format","reason":"While italics are used for long works like books or movies, shorter works like chapter titles should be indicated with quotation marks instead of italics."}]},"studyAid":{"definition":"Use quotation marks to set off the titles of shorter works, such as chapters, poems, articles, and short stories.","example":"My favorite poem is \"The Road Not Taken.\" Please read chapter two, \"The Discovery.\"","strategyClue":"Identify the specific title of the small part or section mentioned, and place quotation marks only around those exact words to clearly separate the title from the rest of the sentence.","link":"https://www.grammar-monster.com/punctuation/using_quotation_marks.htm","linkText":"Grammar Monster - Quotation Marks"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sequence":6,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-quotation-marks-q0007","version":5,"contentHash":"sha256:2068ab5b4d199a47a7e53da0b4dbbc8cad62e6f8e722fc70f1ef97fb5bf6c250","question":"What punctuation should follow a dialogue tag before the quote?","choices":["period","comma","question mark","no punctuation"],"correct":1,"explanation":{"correct":"Answer: comma. A comma is used to separate the dialogue tag (like 'he said') from the exact words being spoken in a quote.","incorrect":[{"choice":"period","category":"incorrect sentence punctuation","reason":"A period ends a full sentence. Placing one before the quote would incorrectly split the dialogue tag from the spoken words."},"",{"choice":"question mark","category":"incorrect terminal punctuation","reason":"Question marks are only used before a quote if the dialogue tag itself is a question, which is not standard for a simple tag like 'he said'."},{"choice":"no punctuation","category":"missing punctuation mark","reason":"Leaving out punctuation makes it hard for the reader to tell where the speaker's name ends and where their words begin."}]},"studyAid":{"definition":"When introducing a quote with a dialogue tag, use a comma after the speaker's verb to connect the tag to the quoted speech.","example":"He asked, 'Are you ready?' vs. She shouted, 'Watch out!'","strategyClue":"Look at the word immediately preceding the quotation mark. If it is a verb of speaking, check if the transition between the tag and the quote feels like a natural pause that needs a soft break.","link":"https://www.grammar-monster.com/punctuation/using_quotation_marks.htm","linkText":"Grammar Monster - Quotation Marks"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sequence":7,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-quotation-marks-q0008","version":3,"contentHash":"sha256:6a1d5cda12cafdb99297d25cd17e45ca45286292b151970262968740527d7a9d","question":"Which sentence is punctuated correctly?","choices":["'I am tired.' Said Mark.","'I am tired,' said Mark.","'I am tired' said Mark.","'I am tired', said Mark."],"correct":1,"explanation":{"correct":"Answer: 'I am tired,' said Mark. Rule or clue: Dialogue punctuation keeps the spoken words inside quotation marks and places commas or end marks with the quoted words. \"'I am tired,' said Mark.\" keeps the spoken words inside quotation marks and places the comma or end mark where dialogue needs it.","incorrect":[{"choice":"'I am tired.' Said Mark.","reason":"\"'I am tired.' Said Mark.\" puts the quotation marks, capitalization, or dialogue punctuation in the wrong place."},"",{"choice":"'I am tired' said Mark.","reason":"\"'I am tired' said Mark.\" does not use the comma needed before the speaker tag."},{"choice":"'I am tired', said Mark.","reason":"\"'I am tired', said Mark.\" leaves the quoted words or their punctuation unfinished."}]},"studyAid":{"definition":"When a dialogue tag follows a quoted statement, the period becomes a comma inside the quotation marks.","example":"\"I'm ready,\" she said. (Not: 'I'm ready.' She said.)","link":"https://www.grammar-monster.com/punctuation/using_quotation_marks.htm","linkText":"Grammar Monster - Quotation Marks"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sequence":8,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-quotation-marks-q0009","version":3,"contentHash":"sha256:30f33fba11acbc964e61046c21a343b99a580932afa360c8258f0182b51085e6","question":"Which is correct when the quote ends with an exclamation?","choices":["'Run!' she yelled.","'Run,' she yelled.","'Run!' She yelled.","'Run' she yelled!"],"correct":0,"explanation":{"correct":"Answer: 'Run!' she yelled. When a quote ends in an exclamation point, the mark goes inside the quotation marks, and the speech tag starts with a lowercase letter unless it is a proper noun.","incorrect":["",{"choice":"'Run,' she yelled.","category":"incorrect punctuation mark","reason":"You replaced the exclamation point with a comma. Since the speaker is shouting, the sentence must keep the exclamation point inside the closing quotation mark."},{"choice":"'Run!' She yelled.","category":"incorrect capitalization","reason":"Even though there is an exclamation mark, 'she' should not be capitalized here because it is part of the same sentence as the quote."},{"choice":"'Run' she yelled!","category":"misplaced punctuation mark","reason":"The exclamation mark belongs to the spoken word 'Run,' so it must be placed inside the closing quotation marks, not after the word 'yelled'."}]},"studyAid":{"definition":"When a quote ends in a question mark or exclamation point, the punctuation mark belongs inside the quotation marks, and the following speech tag starts with a lowercase letter.","example":"'Stop!' she shouted. vs 'Stop' she shouted! (incorrect). 'Are we there?' he asked.","strategyClue":"Check if the speaker is shouting or asking a question inside the quotes. If they are, ensure the punctuation mark is tucked inside the ending quotation mark before moving to the speech tag.","link":"https://www.grammar-monster.com/punctuation/using_quotation_marks.htm","linkText":"Grammar Monster - Quotation Marks"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sequence":9,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-quotation-marks-q0010","version":4,"contentHash":"sha256:d1863b860add4b5ba5ee0d4cacfdec83392d2f8a66ce149431eec5cb9df9bfaf","question":"Which sentence uses quotation marks correctly for scare quotes (doubt or irony)?","choices":["His 'expert' advice made things worse.","His expert advice made things worse.","His \"expert\" advice made things worse.","His 'expert advice' made things worse."],"correct":2,"explanation":{"correct":"Answer: His \"expert\" advice made things worse. Standard English uses double quotation marks, not single ones, to set off words used ironically or to express doubt.","incorrect":[{"choice":"His 'expert' advice made things worse.","category":"incorrect punctuation style","reason":"Single quotation marks are generally reserved for quotes within quotes. For irony or scare quotes, use double quotation marks instead."},{"choice":"His expert advice made things worse.","category":"missing punctuation","reason":"Without quotation marks around 'expert', the reader might think the advice was truly helpful. The marks are needed to show that the advice was actually poor."},"",{"choice":"His 'expert advice' made things worse.","category":"incorrect scope and style","reason":"This uses single marks and incorrectly includes the word 'advice' inside the quotes. Only the word 'expert' should be marked to show the irony."}]},"studyAid":{"definition":"Scare quotes are double quotation marks used around a word to show that the word is being used in an ironic or doubtful way.","example":"My 'brilliant' plan failed (incorrect); My \"brilliant\" plan failed (correct); He is an \"honest\" thief (correct).","strategyClue":"Look for the specific word that sounds like it is being used sarcastically, and ensure you use double marks rather than single marks to highlight it.","link":"https://www.grammar-monster.com/punctuation/using_quotation_marks.htm","linkText":"Grammar Monster - Quotation Marks"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sequence":10,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-quotation-marks-q0011","version":3,"contentHash":"sha256:7855c9e13ad79ccad88cf1be467b02266372547d39e7ecb50447d7bc84dcbbd2","question":"Which sentence correctly quotes a question within a statement?","choices":["She asked, 'Are you coming?'","She asked 'Are you coming'?","She asked, 'Are you coming'?","She asked 'Are you coming?'"],"correct":0,"explanation":{"correct":"Answer: She asked, 'Are you coming?'. When a quotation is a question, the question mark goes inside the closing quotation mark, and a comma is needed to introduce the direct speech after the verb.","incorrect":["",{"choice":"She asked 'Are you coming'?","category":"missing comma and punctuation","reason":"You need a comma after 'asked' to introduce the quote, and the question mark must stay inside the closing quotation mark because the quote itself is the question."},{"choice":"She asked, 'Are you coming'?","category":"misplaced punctuation","reason":"Even though you included the comma, the question mark belongs inside the quotation marks because the person is asking a direct question."},{"choice":"She asked 'Are you coming?'","category":"missing introductory comma","reason":"When a sentence introduces a direct quote with a speech verb like 'asked', you must place a comma immediately before the opening quotation mark."}]},"studyAid":{"definition":"Direct quotations that are questions must have the question mark inside the quotation marks, and an introductory comma usually follows the speaker's verb.","example":"Correct: He asked, 'Where is the map?' Incorrect: He asked 'Where is the map'? / He asked, 'Where is the map'? (missing question mark inside)","strategyClue":"Check for two things: Is there a comma separating the speaker's verb from the quote, and is the question mark hugged by the quotation marks?","link":"https://www.grammar-monster.com/punctuation/using_quotation_marks.htm","linkText":"Grammar Monster - Quotation Marks"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sequence":11,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-quotation-marks-q0012","version":3,"contentHash":"sha256:a69bbf3a95499c1ddd54f0e65c6d893f903abcda051007fd07fabd3df6ac5535","question":"Which is correct for a quote that is a fragment?","choices":["Mark called the game 'exciting.'","Mark called the game, 'exciting.'","Mark called the game 'exciting'.","Mark called the game, 'exciting'."],"correct":0,"explanation":{"correct":"Answer: Mark called the game 'exciting.' When a quote is only a word or a short fragment integrated directly into a sentence, you do not need a comma before the opening quotation mark, and the period belongs inside the closing quotation mark.","incorrect":["",{"choice":"Mark called the game, 'exciting.'","category":"unnecessary comma usage","reason":"Using a comma before a short, integrated word quote is incorrect. Commas are usually reserved for introducing direct speech or formal dialogue."},{"choice":"Mark called the game 'exciting'.","category":"misplaced end punctuation","reason":"In American English, periods should almost always be placed inside the closing quotation mark, even when the quote is just one word."},{"choice":"Mark called the game, 'exciting'.","category":"comma and punctuation","reason":"This choice incorrectly uses both a comma before the quote and places the period outside the closing quotation mark."}]},"studyAid":{"definition":"When adding a short quoted word or phrase into your own sentence, do not use a comma to introduce it, and always place periods and commas inside the quotation marks.","example":"He said the book was 'boring.' She described the sky as 'blue.'","strategyClue":"Check if the quoted part is a full sentence or just a single word acting like a noun or adjective; if it is just a small piece of your own sentence, look for the option that skips the comma and tucks the period safely inside the quote marks.","link":"https://www.grammar-monster.com/punctuation/using_quotation_marks.htm","linkText":"Grammar Monster - Quotation Marks"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sequence":12,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-quotation-marks-q0013","version":3,"contentHash":"sha256:7117f313cea468a771ebe16b1b64c3693c7dfa8b151266ea9085303b9031e3f5","question":"Which sentence is punctuated correctly?","choices":["'Let's eat, Grandma!'","'Let's eat Grandma!'","'Let's eat Grandma'!","'Let's eat, Grandma'!"],"correct":0,"explanation":{"correct":"Answer: 'Let's eat, Grandma!'. The comma is necessary before the name 'Grandma' because it indicates a direct address. In English, we set off the name of the person being spoken to with a comma.","incorrect":["",{"choice":"'Let's eat Grandma!'","category":"missing direct address comma","reason":"Without the comma before 'Grandma,' the sentence literally suggests that you are going to eat your grandmother! The comma shows that you are speaking TO her, not about eating her."},{"choice":"'Let's eat Grandma'!","reason":"Not: 'Let's eat Grandma'! \"'Let's eat Grandma'!\" leaves the quoted words or their punctuation unfinished."},{"choice":"'Let's eat, Grandma'!","category":"incorrect quotation closure","reason":"All end punctuation for a piece of dialogue should be placed inside the closing quotation mark. Moving the exclamation mark outside makes the sentence punctuation look incomplete."}]},"studyAid":{"definition":"Use a comma to separate the name of the person you are talking to from the rest of your sentence. Always place end punctuation inside the quotation marks for direct speech.","example":"Correct: 'Hello, Sam!' vs. Incorrect: 'Hello Sam!'","strategyClue":"Ask yourself if you are talking TO the person or ABOUT the person. If you are talking to them, place a comma before their name. Check that all punctuation belonging to the speaker stays tucked inside the final quotation mark.","link":"https://www.grammar-monster.com/punctuation/using_quotation_marks.htm","linkText":"Grammar Monster - Quotation Marks"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sequence":13,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-quotation-marks-q0014","version":3,"contentHash":"sha256:5dc39690b2ade426a9ad003136de11038de0384f91ad3524a7af751c534d18c7","question":"Which uses quotation marks correctly for a proverb or saying?","choices":["My grandma always said, 'A friend in need is a friend indeed.'","My grandma always said A friend in need is a friend indeed.","My grandma always said, A friend in need is a friend indeed.","My grandma always said 'A friend in need is a friend indeed.'"],"correct":0,"explanation":{"correct":"Answer: My grandma always said, 'A friend in need is a friend indeed.' Direct quotations must be enclosed in quotation marks and typically introduced by a comma.","incorrect":["",{"choice":"My grandma always said A friend in need is a friend indeed.","category":"missing quotation marks","reason":"This sentence fails to include quotation marks around the spoken words, making it unclear where the proverb begins and ends."},{"choice":"My grandma always said, A friend in need is a friend indeed.","category":"missing quotation marks","reason":"Even though this sentence uses a comma to introduce the speech, it is missing the necessary quotation marks to identify the exact words being spoken."},{"choice":"My grandma always said 'A friend in need is a friend indeed.'","category":"missing introductory comma","reason":"When introducing a direct quote after a speech verb, you must use a comma before the opening quotation mark to separate the speaker from the words."}]},"studyAid":{"definition":"Quotation marks are used to show the exact words spoken or written by someone else. They must always appear in pairs to 'bookend' the quoted text.","example":"He said, 'Hello!' / 'I love pizza,' she told me. / 'Wait for me,' he called out.","strategyClue":"Look for the comma separating the speech tag (like 'she said') from the speech itself. Ensure both the opening and closing quotation marks are present around the spoken words.","link":"https://www.grammar-monster.com/punctuation/using_quotation_marks.htm","linkText":"Grammar Monster - Quotation Marks"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sequence":14,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-quotation-marks-q0015","version":6,"contentHash":"sha256:f83919a959e6c26c5d1d6c5ecc0922df954a98331809358ecefc8929a8a335d1","question":"Which sentence correctly punctuates a quotation split by a speaker tag?","choices":["\"I found the map,\" said Nora, \"but the trail is missing.\"","\"I found the map,\" said Nora \"but the trail is missing.\"","\"I found the map\" said Nora, \"but the trail is missing.\"","\"I found the map,\" said Nora, \"But the trail is missing.\""],"correct":0,"studyAid":{"definition":"Dialogue keeps spoken words inside quotation marks and uses punctuation to connect speaker tags.","example":"\"The bus is here,\" announced Mr. Lee.","link":"https://www.grammar-monster.com/lessons/quotation_(speech)_marks_punctuation_in_or_out.htm","linkText":"Grammar Monster - Quotation Marks"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["punctuation","sentence mechanics","editing"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sequence":15,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]},"explanation":{"correct":"Answer: \"I found the map,\" said Nora, \"but the trail is missing.\" Rule or clue: When a new speaker talks, start a new quoted sentence and keep each speaker’s words inside quotation marks. '\"I found the map,\" said Nora, \"but the trail is missing.\"' keeps the spoken words inside quotation marks and places the comma or end mark where dialogue needs it.","incorrect":["",{"choice":"\"I found the map,\" said Nora \"but the trail is missing.\"","reason":"Not: \"I found the map,\" said Nora \"but the trail is missing.\" '\"I found the map,\" said Nora \"but the trail is missing.\"' puts the quotation marks, capitalization, or dialogue punctuation in the wrong place."},{"choice":"\"I found the map\" said Nora, \"but the trail is missing.\"","reason":"Not: \"I found the map\" said Nora, \"but the trail is missing.\" '\"I found the map\" said Nora, \"but the trail is missing.\"' does not use the comma needed before the speaker tag."},{"choice":"\"I found the map,\" said Nora, \"But the trail is missing.\"","reason":"Not: \"I found the map,\" said Nora, \"But the trail is missing.\" '\"I found the map,\" said Nora, \"But the trail is missing.\"' puts the quotation marks, capitalization, or dialogue punctuation in the wrong place."}]}},{"id":"punctuation-quotation-marks-q0016","version":3,"contentHash":"sha256:4186f419b4d463ba964065b958086191612d461342e11cb21caff782b41cb685","question":"Choose the sentence that is punctuated correctly.","choices":["“Did you remember to buy milk,” asked Danny?","“Did you remember to buy milk”? asked Danny.","Danny asked, “Did you remember to buy milk?” to","Danny asked, “Did you remember to buy milk”?"],"correct":2,"explanation":{"correct":"Answer: Danny asked, “Did you remember to buy milk?”. In English, the question mark belongs inside the quotation marks because it is part of the speaker's question, and the period follows the entire sentence structure correctly.","incorrect":[{"choice":"“Did you remember to buy milk,” asked Danny?","category":"comma instead of question","reason":"Because the speaker is asking a question, you must use a question mark inside the quotation marks instead of a comma."},{"choice":"“Did you remember to buy milk”? asked Danny.","category":"misplaced punctuation","reason":"The question mark is part of the quoted speech. Always keep it inside the quotation marks rather than placing it after them."},"",{"choice":"Danny asked, “Did you remember to buy milk”?","reason":"Not: Danny asked, “Did you remember to buy milk”? \"Danny asked, “Did you remember to buy milk”?\" leaves the quoted words or their punctuation unfinished."}]},"studyAid":{"definition":"When a direct quote is a question, the question mark goes inside the quotation marks. The rest of the sentence should end with a period unless the entire sentence itself is a question.","example":"He asked, \"Where is my hat?\" | \"Are we ready?\" she whispered.","strategyClue":"Look at the words inside the quotation marks. If those words are asking something, place the punctuation mark inside the closing quote before continuing the sentence.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sourceFile":"Advanced Quiz 1_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":1,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":16,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-quotation-marks-q0017","version":3,"contentHash":"sha256:180be6c7ad305d42da3e16def8f75267ff3d32e8547953669710aa72f54b52a1","question":"Choose the punctuation that means Joseph’s mother is speaking to him. Joseph mother said you have to make your bed.","choices":["Joseph’s mother said you have to make your bed.","“Joseph, Mother said you have to make your bed.”","Joseph Mother said, “You have to make your bed.”","“Joseph,” Mother said, “you have to make your bed.”"],"correct":3,"explanation":{"correct":"Answer: “Joseph,” Mother said, “you have to make your bed.” This option correctly uses quotation marks to surround the exact words spoken and a comma to set off the name of the person being addressed.","incorrect":[{"choice":"Joseph’s mother said you have to make your bed.","category":"missing quotation marks","reason":"This sentence describes someone speaking but does not use quotation marks to show the exact words spoken aloud, making it look like a statement of fact rather than dialogue."},{"choice":"“Joseph, Mother said you have to make your bed.”","category":"incorrect quotation scope","reason":"The quotation marks here incorrectly group the name and the narration together. Quotation marks should only contain the actual words spoken by the speaker."},{"choice":"Joseph Mother said, “You have to make your bed.”","category":"missing address punctuation","reason":"When speaking directly to a person, you must use a comma to set off their name, as it acts as a direct address. This sentence lacks the comma after 'Joseph'."},""]},"studyAid":{"definition":"Direct speech uses quotation marks to surround spoken words, and a comma is used to separate the speaker's name when they are being addressed directly.","example":"“Hello, Sam,” said Tom. / “Look at that bird,” Sarah exclaimed.","strategyClue":"Look for the person being spoken to and identify the exact words coming out of their mouth. Ensure there is a comma before the name if it starts the sentence, and wrap only the spoken words in quotation marks.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sourceFile":"Advanced Quiz 1_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":3,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":17,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-quotation-marks-q0018","version":3,"contentHash":"sha256:c43116f1687b634466573bbb8bbc6944e72ee801cdf6209a100791488ff8bd4d","question":"What is the correct way to write the sentence below? My father asked me what are you wearing to the dance.","choices":["The sentence is correct.","My father asked me, “what are you wearing to t he dance?”","My father asked me, “What are you wearing to the dance”?","My father asked me, “What are you wearing to the dance?”"],"correct":3,"explanation":{"correct":"Answer: My father asked me, “What are you wearing to the dance?” Direct speech requires a comma before the opening quotation mark and a question mark inside the closing quotation mark.","incorrect":[{"choice":"The sentence is correct.","category":"missing punctuation marks","reason":"The original sentence is missing a comma to introduce the quote and quotation marks to show exactly what was said."},{"choice":"My father asked me, “what are you wearing to t he dance?”","category":"capitalization and spacing","reason":"Direct speech should start with a capital letter inside the quotes, and 't he' has an incorrect space in the middle of the word 'the'."},{"choice":"My father asked me, “What are you wearing to the dance”?","category":"misplaced terminal punctuation","reason":"When a quote is a question, the question mark must be placed inside the closing quotation mark, not outside of it."},""]},"studyAid":{"definition":"Direct quotations need a comma before the first quotation mark, and the first word inside the quotes should be capitalized. Punctuation like question marks belongs inside the closing quotation mark.","example":"He asked, \"Where is my hat?\" (Correct) vs. He asked \"Where is my hat\"? (Incorrect)","strategyClue":"Check for three specific things: is there a comma before the quote starts, is the first word capitalized inside the quotes, and is the question mark located inside the final quote mark?","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sourceFile":"Advanced Quiz 1_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":9,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":18,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-quotation-marks-q0022","version":3,"contentHash":"sha256:9e40ce44eb98cd37945d86349f1072a61bec29283de309dd1a102c2397f51b67","question":"Read the following paragraph and determine which sentence has the incorrect punctuation of direct speech. (1) (2) I was so excited for the first day of school. My alarm went off, and I jumped out of bed. n’t forget to brush your teeth before you come downstairs” mom said. (3) “Do (4) “Where’s my toothbrush?” I replied back.","choices":["Sentence 1","Sentence 2","Sentence 3","Sentence 4"],"correct":2,"explanation":{"correct":"Answer: Sentence 3. This sentence is incorrect because the opening quotation mark is missing at the beginning of the spoken words 'Don’t forget'. Direct speech must always start with a capital letter inside quotation marks.","incorrect":[{"choice":"Sentence 1","category":"correct punctuation","reason":"This sentence contains no dialogue, so it does not require quotation marks. It correctly ends with a period."},{"choice":"Sentence 2","category":"correct punctuation","reason":"This sentence describes actions rather than dialogue, so it does not need quotation marks. The punctuation here is used correctly."},"",{"choice":"Sentence 4","category":"correct punctuation","reason":"This sentence correctly uses quotation marks to enclose the spoken question 'Where’s my toothbrush?' and properly places the closing mark after the question mark."}]},"studyAid":{"definition":"Direct speech needs quotation marks around the exact words spoken, and the first word inside the marks should be capitalized.","example":"Correct: \"Hello!\" she said. Incorrect: Hello! she said. Correct: He asked, \"Are you ready?\" Incorrect: He asked, Are you ready?","strategyClue":"Check every sentence that includes a conversation. Look for the start of the spoken words and ensure there is a quotation mark before the first letter of the sentence.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"apply-with-context","languageDemand":"passage-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sourceFile":"Advanced Quiz 3_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":2,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":22,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-quotation-marks-q0031","version":3,"contentHash":"sha256:f48cb5b78ab1ff2abcd5aa019af82ea394456ccbf107997818d4aee362747493","question":"Choose the punctuation that means a third character is shouting at Joseph to tell him his mother said to make his bed. Joseph mother said you have to make your bed.","choices":["“Jose ph,” Mother said, “you have to make your bed!”","“Joseph, Mother said you have to make your bed!”","“Joseph,” Mother said, “you have to make your b ed?”","“Joseph, Mother said you have to make your bed.”"],"correct":1,"explanation":{"correct":"Answer: “Joseph, Mother said you have to make your bed!” Use a comma to address Joseph directly, capitalize 'Mother' because it acts as a name here, and use an exclamation mark to show that someone is shouting.","incorrect":[{"choice":"“Jose ph,” Mother said, “you have to make your bed!”","category":"Incorrect word spacing","reason":"The name 'Joseph' should not be split into two words. Punctuation also includes how we spell and group letters in names."},"",{"choice":"“Joseph,” Mother said, “you have to make your b ed?”","category":"Incorrect punctuation and spacing","reason":"The word 'bed' is misspelled with a space, and a question mark is used instead of an exclamation mark, which does not correctly show the act of shouting."},{"choice":"“Joseph, Mother said you have to make your bed.”","category":"Missing shout punctuation","reason":"The period at the end shows a normal statement, not someone shouting. An exclamation mark is needed to convey the loud volume described."}]},"studyAid":{"definition":"Direct address uses a comma before a name, and exclamation marks are used at the end of sentences to indicate strong emotion or shouting.","example":"Hey, Tom, watch out! Stop running, Sarah!","strategyClue":"Look for three specific elements: a comma used to set off the person being spoken to, the correct spelling of the name, and the ending mark that signals a loud or strong voice.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"apply-with-context","languageDemand":"passage-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sourceFile":"Advanced Quiz 4_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":1,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":31,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-quotation-marks-q0045","version":3,"contentHash":"sha256:45491bec16be357defff5122bc66f4367a2baa4ab5882703dfcd3eacb943d371","question":"Which sentence uses commas and quotation marks correctly?","choices":["M artha asked, “How long were you on vacation f or?”","“Martha asked, how long were you on vacation for?”","Martha asked? “How long were you on vacation for.”","Martha asked “How long were you on vacation for?”"],"correct":0,"explanation":{"correct":"Answer: Martha asked, “How long were you on vacation for?”. When introducing a direct quote, use a comma before the opening quotation mark to separate the dialogue from the speaker.","incorrect":["",{"choice":"“Martha asked, how long were you on vacation for?”","category":"misplaced quotation marks","reason":"You should only place quotation marks around the actual words spoken. Placing them around the entire sentence makes it look like the speaker is quoting themselves."},{"choice":"Martha asked? “How long were you on vacation for.”","category":"incorrect punctuation marks","reason":"The question mark belongs inside the quotation marks at the end of the question, and a comma should follow 'asked' rather than a question mark."},{"choice":"Martha asked “How long were you on vacation for?”","category":"missing comma","reason":"A comma is required to pause after the reporting verb 'asked' before starting the direct quote."}]},"studyAid":{"definition":"When writing direct speech, put a comma after the reporting verb (like 'said' or 'asked') and keep the punctuation for the quote inside the quotation marks.","example":"He said, \"Hello!\" / She asked, \"Where are you going?\"","strategyClue":"Look for the spot where the speaker's words begin. Before that spot, check for a comma; inside the end quote, ensure the sentence has its own specific punctuation like a question mark.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sourceFile":"Basic Quiz 1_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":5,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":45,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-quotation-marks-q0051","version":4,"contentHash":"sha256:aa089a900db024032c541101f57962ed782b8ee2767442c3f597700b76ed7aea","question":"Choose the punctuation mark that is needed in the sentence. If no m ore punctuation is needed, choo se “None.” “Mom wo n’t let us have another coo kie,” said Joanne.","choices":[".",",","!","No ne"],"correct":3,"explanation":{"correct":"Answer: None. The sentence already contains a comma after the word 'cookie' to separate the quotation from the speaker tag, which is the only punctuation needed at that spot.","incorrect":[{"choice":".","category":"incorrect sentence punctuation","reason":"Adding a period here would create a sentence fragment and interrupt the flow between the dialogue and the speaker, which is already separated by the existing comma."},{"choice":",","category":"duplicate punctuation","reason":"A comma is already present after the word 'cookie'. Adding another one would be redundant and grammatically incorrect."},{"choice":"!","category":"incorrect sentence punctuation","reason":"An exclamation point changes the meaning of the speaker tag and is not required here, as the comma already performs the correct role of separating the quote from the tag."},""]},"studyAid":{"definition":"When writing dialogue, a comma is used inside the quotation marks to separate the spoken words from the speaker tag.","example":"\"I love reading,\" said Sam. / \"Look at that!\" shouted Ali.","strategyClue":"Check the sentence for existing punctuation marks. If you see that the grammar rule is already satisfied by a mark already present, choose the option that implies no further additions are required.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"apply-with-context","languageDemand":"passage-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sourceFile":"Basic Quiz 2_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":1,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":51,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-quotation-marks-q0055","version":3,"contentHash":"sha256:22e29c4aee769702fba552afb0c4ac2ab9c0ae669d9baf9d0530cd95c252cc3b","question":"Which sentence uses commas and quotation marks correctly?","choices":["Mom said “Yes!”","Mom said, “Yes!”","“Mom said, Yes!”","Mo m said. “Yes!”"],"correct":1,"explanation":{"correct":"Answer: Mom said, “Yes!”. A comma is needed to separate the speaker from the spoken words, and quotation marks must enclose only the part being said.","incorrect":[{"choice":"Mom said “Yes!”","category":"missing introductory comma","reason":"When a reporting verb like 'said' introduces a direct quote, you must place a comma after the verb and before the opening quotation mark."},"",{"choice":"“Mom said, Yes!”","category":"misplaced quotation marks","reason":"The quotation marks are only for the words spoken aloud. 'Mom said' is the speaker, so it should not be inside the marks."},{"choice":"Mo m said. “Yes!”","category":"incorrect internal punctuation","reason":"You cannot use a period to separate the speaker from the quote. Also, ensure there is no space in the middle of words like 'Mom'."}]},"studyAid":{"definition":"When using direct quotations, use a comma after the speaker's tag and enclose the spoken words in quotation marks.","example":"He said, “Hello.” / “Come here,” she whispered.","strategyClue":"Identify the actual words spoken out loud. Draw a line between the speaker and the spoken words to see where the comma and the opening quotation mark should go.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sourceFile":"Basic Quiz 2_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":5,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":55,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-quotation-marks-q0065","version":3,"contentHash":"sha256:59bdda09afb9f4d6e982dd7d1d2d69456d903e319beba82243d5b4cb1a24fde6","question":"Which sentence uses commas and quotation marks correctly?","choices":["Are we there yet, “asked Justin?”","“Are we there yet?” asked Justin.","“Are we there yet?”, asked Justin.","“Are we there yet?” asked Justin?"],"correct":1,"explanation":{"correct":"Answer: “Are we there yet?” asked Justin. When a direct quote is a question, the question mark goes inside the quotation marks, and the dialogue tag that follows is separated by a comma or remains outside the quote.","incorrect":[{"choice":"Are we there yet, “asked Justin?”","category":"misplaced quotation marks","reason":"The quotation marks should surround only the words spoken by Justin. Placing the tag 'asked Justin' inside the quotes is incorrect."},"",{"choice":"“Are we there yet?”, asked Justin.","category":"comma placement error","reason":"You do not need a comma after a closing quotation mark if the quote already ends with a question mark. The question mark is sufficient to separate the dialogue from the tag."},{"choice":"“Are we there yet?” asked Justin?","category":"incorrect end punctuation","reason":"The question mark should be inside the quotation marks to show that the dialogue itself is a question. Adding a second question mark at the very end of the sentence is unnecessary and confusing."}]},"studyAid":{"definition":"Direct quotations must be enclosed in quotation marks, and the punctuation for the dialogue belongs inside those marks. If a question is asked, the question mark acts as the end punctuation for the quote.","example":"\"Hello!\" she shouted. / \"Where are we going?\" he asked. / She asked, \"Do you like pizza?\"","strategyClue":"First, identify the exact words being spoken. Next, check if the sentence is a statement, a question, or an exclamation. Make sure the punctuation mark that matches the tone of the speech is placed inside the closing quotation mark.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sourceFile":"Basic Quiz 3_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":5,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":65,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-quotation-marks-q0071","version":4,"contentHash":"sha256:9ec1b18cc66242961b4582115b4c998bbeb2f03a7d79b3eb22fcedb61592373e","question":"Choose the punctuation mark that is needed in the sentence. If no more punctuation is needed, choose “None.” “This dessert is delicious, said Jamie.","choices":[",","?","”","None"],"correct":2,"explanation":{"correct":"Answer: ”. The sentence begins with quotation marks before 'This', so you must use a closing quotation mark to show where the character's speech ends.","incorrect":[{"choice":",","category":"missing closing punctuation","reason":"Using another comma after 'delicious' would leave the quotation open and unfinished. You need a closing mark to tell the reader the character has stopped speaking."},{"choice":"?","category":"wrong terminal punctuation","reason":"A question mark is used to show a question is being asked. Since this sentence is a statement, a question mark does not fit."},"",{"choice":"None","category":"missing closing punctuation","reason":"Because the sentence starts with an opening quotation mark, the quote must be closed. Leaving it out means the sentence is incomplete."}]},"studyAid":{"definition":"Direct quotations, which are the exact words someone says, must be enclosed within a pair of quotation marks.","example":"\"I love to read,\" said Sam. / \"Look at that dog!\" yelled Jen.","strategyClue":"Look at the very beginning of the sentence to see if there is an opening quotation mark. If you see one, you must search for the end of the spoken words and place the matching closing mark there.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sourceFile":"Basic Quiz 4_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":1,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":71,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-quotation-marks-q0075","version":3,"contentHash":"sha256:3291ebf28b1649fc5dc3af7fbf325191172ce5a1d92c99d3342427df8c592215","question":"Which sentence uses commas and quotation marks correctly?","choices":["“It’s a good book” Lee said.","“It’s a good book,” Lee said.","“It’s a good book, Lee said”.","“It’s a good book”, Lee said."],"correct":1,"explanation":{"correct":"Answer: “It’s a good book,” Lee said. When a quotation comes before the speaker tag, you must place a comma inside the closing quotation mark to separate the dialogue from the rest of the sentence.","incorrect":[{"choice":"“It’s a good book” Lee said.","category":"missing comma","reason":"This sentence is missing a comma to separate the dialogue from the speaker tag. Without the comma inside the quotes, the sentence feels like it is rushing from the dialogue into the action."},"",{"choice":"“It’s a good book, Lee said”.","category":"misplaced punctuation","reason":"The closing quotation mark must come after the comma, not after the speaker tag. Punctuation that ends the dialogue should always be tucked inside the quotation marks."},{"choice":"“It’s a good book”, Lee said.","category":"misplaced comma","reason":"The comma belongs inside the quotation marks when it is part of the dialogue's ending. Placing it after the closing quote is incorrect in this structure."}]},"studyAid":{"definition":"When a speaker tag (like 'he said') follows a direct quote, place a comma inside the closing quotation mark to connect the two parts of the sentence.","example":"“I am tired,” she whispered. / “Can we go?” he asked.","strategyClue":"Look at where the speaking ends and the tag begins. Identify which choice keeps the punctuation snug inside the quotation marks before the speaker is named.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sourceFile":"Basic Quiz 4_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":5,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":75,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-quotation-marks-q0082","version":3,"contentHash":"sha256:c687c7146fd98f22f6202735b2fb4356fba4c4261c1abe6124784bf9728a3e84","question":"What is the correct way to write the sentence bel ow? Tori’s French teacher asked her what the answer was to the question.","choices":["The sentence is correct.","Tori’s French teacher asked her “what the answer was to the question?”","“Tori’s French teacher asked her what the answer was to the question.”","Tori’s French teacher asked her, “what the answer was to the question.”"],"correct":0,"explanation":{"correct":"Answer: The sentence is correct. This sentence is an indirect question, meaning it reports what someone asked without using their exact words. Therefore, it does not require quotation marks or a question mark.","incorrect":["",{"choice":"Tori’s French teacher asked her “what the answer was to the question?”","category":"incorrect punctuation and quoting","reason":"This choice incorrectly uses quotation marks for a statement that isn't a direct quote and adds a question mark to an indirect report, which is not allowed."},{"choice":"“Tori’s French teacher asked her what the answer was to the question.”","category":"unnecessary quotation marks","reason":"You should not place quotation marks around the entire sentence unless the whole thing is a direct quote being spoken by someone else. Here, it is just a normal descriptive sentence."},{"choice":"Tori’s French teacher asked her, “what the answer was to the question.”","category":"comma and quote misuse","reason":"The comma and quotation marks are misused here. When you report what someone asked without using their exact words, you do not use a comma or quotes."}]},"studyAid":{"definition":"An indirect question reports what someone asked using your own words instead of their exact words. Indirect questions do not use quotation marks or question marks at the end.","example":"Direct: She asked, \"Where is my book?\" Indirect: She asked where her book was.","strategyClue":"Check if the sentence is repeating exact spoken words or if it is describing the information that was requested. If the words after 'asked' are not in quotation marks in the original speaker's mouth, you do not need special punctuation.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sourceFile":"Proficient Quiz 1_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":2,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":82,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-quotation-marks-q0085","version":3,"contentHash":"sha256:620e9270b3795509dec0e4392f4ed38cdae80a04d1350669a2cf97bce2d030e6","question":"Which sentence uses commas and quotation marks correctly?","choices":["“I answered the door,” and said I think you have the wrong house.","I answered the door and said, “I think you have the wrong house.”","“I answered the door” and said, “I think you have the wrong house.”","I answered the door and said, “that I think you have the wrong house.”"],"correct":1,"explanation":{"correct":"Answer: I answered the door and said, “I think you have the wrong house.”. When you introduce a direct quote with a dialogue tag like 'said', place a comma after the tag and before the opening quotation mark, and ensure the dialogue begins with a capital letter and ends with the final punctuation inside the quote marks.","incorrect":[{"choice":"“I answered the door,” and said I think you have the wrong house.","category":"misplaced quotation marks","reason":"This choice incorrectly puts quotation marks around the speaker's actions instead of their actual spoken words. You should only use quotation marks for what the person is saying aloud."},"",{"choice":"“I answered the door” and said, “I think you have the wrong house.”","category":"improper quotation usage","reason":"Adding quotation marks around the first part of the sentence suggests the narrator is speaking those words aloud, which is incorrect here because those are narrative actions, not dialogue."},{"choice":"I answered the door and said, “that I think you have the wrong house.”","category":"incorrect indirect speech","reason":"When using direct quotation marks, you should quote the exact words spoken. Including 'that' inside the quotation marks changes the sentence into an indirect statement, which should not use quotation marks at all."}]},"studyAid":{"definition":"Direct quotations represent the exact words spoken by a person and must be enclosed in quotation marks, preceded by a comma after the reporting verb (like 'said' or 'asked').","example":"He said, “I am happy.” (Correct) vs He said “I am happy” (Incorrect - missing comma).","strategyClue":"Look at the sentence and identify exactly what the person said out loud. Only put quotation marks around those specific words, and make sure there is a comma separating the narrator's words from the speaker's words.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sourceFile":"Proficient Quiz 1_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":5,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":85,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-quotation-marks-q0092","version":3,"contentHash":"sha256:5a591d7e341c9becc1fe1a02688662547654cd1c64bfe01b99b789c2cd906cc9","question":"Where in the following sentence would you place a comma? “I was thinking” she said “what should I’make for dinner?”","choices":["after the word “thinking” and after the word “what”","after the word “said” and after the word “should”","after the word “thinking” and after the word “said”","after the word “said” and after the word “dinner”"],"correct":2,"explanation":{"correct":"Answer: after the word “thinking” and after the word “said”. When a sentence is interrupted by a dialogue tag like \"she said,\" you must place a comma inside the quotation marks at the end of the first part of the quote, and another comma after the dialogue tag before the quote resumes.","incorrect":[{"choice":"after the word “thinking” and after the word “what”","category":"incorrect comma placement","reason":"Placing a comma after \"what\" would incorrectly break the second part of the question. You need the second comma to separate the dialogue tag \"she said\" from the rest of the speech."},{"choice":"after the word “said” and after the word “should”","category":"incorrect comma placement","reason":"Placing a comma after \"should\" splits the phrase \"what should I\" in a way that doesn't follow dialogue punctuation rules. The comma must come immediately after the tag \"said.\""},"",{"choice":"after the word “said” and after the word “dinner”","category":"incorrect comma placement","reason":"You missed the comma needed after \"thinking\" to close the first half of the quotation. Additionally, the comma should never be placed after \"dinner\" because that is where the final question mark belongs."}]},"studyAid":{"definition":"When a speaker's words are interrupted by a dialogue tag, commas are used to set off the speaker's name or tag from the rest of the sentence.","example":"\"Hello,\" she said, \"how are you?\" or \"I'm tired,\" he whispered, \"but I want to play.\"","strategyClue":"Identify the dialogue tag (the part describing who is talking) and look for the breaks where the speaker's speech stops and starts again. Place your commas at the transition points between the spoken words and the tag.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sourceFile":"Proficient Quiz 2_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":2,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":92,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-quotation-marks-q0102","version":3,"contentHash":"sha256:79c85c3dfed278658599f2373bcb9cf881648c146338814d2d9f5cb61c20b697","question":"Read the following paragraph and determine which sentence has the incorrect punctuation of direct speech. (1) I got to basketball practice late, because my alarm didn’t go off. (2) “Run laps,” my coach said. (3) “Do I really have to I asked him.” (4) My coach responded, “Yes, get on? the court!”","choices":["Sentence 1","Sentence 2","Sentence 3","Sentence 4"],"correct":2,"explanation":{"correct":"Answer: Sentence 3. In direct speech, the closing quotation mark must come after the spoken words and before the speaker tag. Sentence 3 incorrectly places the closing quote after the speaker tag 'I asked him' instead of immediately after the question.","incorrect":[{"choice":"Sentence 1","category":"Correct punctuation","reason":"Sentence 1 does not contain direct speech, so it follows standard sentence punctuation rules correctly. There is no error here."},{"choice":"Sentence 2","category":"Correct quotation usage","reason":"Sentence 2 correctly places the comma inside the closing quotation marks and identifies the speaker correctly. This follows standard punctuation rules."},"",{"choice":"Sentence 4","category":"Correct punctuation","reason":"While Sentence 4 contains a strange typo with the question mark, it correctly places the quotation marks around the spoken words as a whole, unlike the fundamental structural error in Sentence 3."}]},"studyAid":{"definition":"When writing direct speech, place quotation marks only around the words the person actually says, not around the words that tell us who is speaking.","example":"\"Hello,\" she said. / \"Where are you going?\" he asked.","strategyClue":"Identify the exact words spoken by the character and verify that the quotation marks hug only those words, ending before the attribution or speaker tag begins.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"passage-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sourceFile":"Proficient Quiz 3_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":2,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":102,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-quotation-marks-q0113","version":3,"contentHash":"sha256:835b692f6b469d6546a05ed0b443fb7ab489fc462754b397bd49b71b64b26721","question":"How should the following sentence be punctuated? “Don’t forget to feed the dog before you leave” Mom said.","choices":["A quotation mark after the word said","A comma after the word leave","forget A comma after the word","A period after the word leave"],"correct":1,"explanation":{"correct":"Answer: A comma after the word leave. When a sentence ends with a quotation before a dialogue tag like 'Mom said,' you must place a comma inside the closing quotation marks to separate the speech from the speaker.","incorrect":[{"choice":"A quotation mark after the word said","category":"incorrect quotation placement","reason":"Quotation marks should only surround the words being spoken. The dialogue tag 'Mom said' is not part of the spoken sentence, so it stays outside the marks."},"",{"choice":"forget A comma after the word","category":"misplaced punctuation","reason":"Placing a comma after 'forget' breaks the flow of the command 'Don’t forget to feed the dog.' Punctuation in dialogue should only be used to separate speech from the speaker."},{"choice":"A period after the word leave","category":"incorrect terminal punctuation","reason":"When a dialogue tag like 'Mom said' follows a quote, the quote ends with a comma instead of a period to show that the sentence continues into the speaker's name."}]},"studyAid":{"definition":"When a direct quote comes before a speaker tag, place a comma inside the closing quotation marks and end the entire sentence with a period.","example":"\"Hello,\" she said. \"I am here,\" he whispered.","strategyClue":"Look at where the spoken words end and the speaker's name begins. Identify the separator needed to bridge the gap between the character's voice and the tag that describes who is talking.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["punctuation","mechanics","language","grade 4"],"feedbackFocus":"use the mechanics or punctuation rule and sentence context to compare each answer choice","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sourceFile":"Proficient Quiz 4_Language_Mechanics and Punctuation_ MAP 4th Grade.pdf","sourceQuestionNumber":3,"sourceCategory":"mechanics-and-punctuation","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":113,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-quotation-marks-q0038","version":3,"contentHash":"sha256:9765127133e9a21a4de7c29d2be50061e4d3e86c3ce70d7c68c50a41c83f0396","question":"Which sentence uses correct punctuation?","choices":["“He said, I’d like to see that.”","He said “I’d like to see that.”","He said, “I’d like to see that.”","He said, “I’d like to see that”."],"correct":2,"explanation":{"correct":"Answer: He said, “I’d like to see that.” In this sentence, the comma is used correctly to introduce a direct quotation, and the period is placed inside the closing quotation mark.","incorrect":[{"choice":"“He said, I’d like to see that.”","category":"incorrect quotation marks","reason":"This choice puts quotation marks around the entire sentence. Quotation marks should only surround the words that were actually spoken by the person."},{"choice":"He said “I’d like to see that.”","category":"missing introductory comma","reason":"When a reporting verb like 'said' introduces a direct quote, you must place a comma after the verb to separate it from the quoted text."},"",{"choice":"He said, “I’d like to see that”.","reason":"\"He said, “I’d like to see that”.\" leaves the quoted words or their punctuation unfinished."}]},"studyAid":{"definition":"When using direct quotations, use a comma after the speaker's verb and ensure the end punctuation of the quote stays inside the quotation marks.","example":"She shouted, “Watch out!” / He asked, “Are you coming?” / “I am tired,” she whispered.","strategyClue":"Check three specific spots: is there a comma after the speaker's verb, do the quotation marks only surround the spoken words, and is the final punctuation mark tucked inside the closing quote?","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sourceFile":"Language Usage_ Proficient 1_4th grade.pdf","sourceQuestionNumber":38,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":38,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-quotation-marks-q0116","version":3,"contentHash":"sha256:c6e1f02be37532d905276c8a7b0d3d371f0d416191be77ecbd9c29f18600b339","question":"Choose the sentence that shows correct punctuation?","choices":["“D o we have apples? asked Trevor.”","“Do we have apples”? asked Trevor.","“D o we have apples?” asked Trevor.","“Do we have apples,” asked Trevor."],"correct":2,"explanation":{"correct":"Answer: “Do we have apples?” asked Trevor. Quotation marks enclose the exact words spoken, and the question mark must go inside the closing quotation mark because the spoken words themselves form a question.","incorrect":[{"choice":"“D o we have apples? asked Trevor.”","reason":"Not: “D o we have apples? asked Trevor.” \"“D o we have apples? asked Trevor.”\" puts the quotation marks, capitalization, or dialogue punctuation in the wrong place."},{"choice":"“Do we have apples”? asked Trevor.","category":"misplaced punctuation","reason":"When a quote is a question, the question mark belongs inside the quotation marks. Placing it outside makes it look like the speaker isn't the one asking the question."},"",{"choice":"“Do we have apples,” asked Trevor.","category":"incorrect punctuation mark","reason":"Because the sentence asks a question, it needs a question mark rather than a comma. Commas are used for statements, but question marks are used for inquiries."}]},"studyAid":{"definition":"Direct quotations must be enclosed in quotation marks, and punctuation that belongs to the spoken sentence should stay inside the marks.","example":"“Where are you going?” he asked. She replied, “I am going home.”","strategyClue":"Ask yourself: 'Is the character asking a question?' If they are, place the question mark inside the quote to capture their exact tone before moving to the tag that names the speaker.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":70,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sourceFile":"Language Usage_Advanced 1_4th grade.pdf","sourceQuestionNumber":14,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":116,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-quotation-marks-q0131","version":3,"contentHash":"sha256:3af66a2b5ad33635b55b02a86811b9b3f9b2a9ad14b5b6e4138ce825604f7ebf","question":"Choose the punctuation that means Rachel’s mother is speaking to her.","choices":["Rachel mother said you have to take out the trash.","“Rachel, Mother said you have to take out the trash.”","Rachel Mother said, “You have to take out the trash.”","“Rachel,” Mother said, “you have to take out the trash.”"],"correct":3,"explanation":{"correct":"Answer: “Rachel,” Mother said, “you have to take out the trash.” This is the correct choice because a direct quotation must be enclosed in quotation marks, and the comma separating the name addressed must be inside the quotation marks when someone is being spoken to.","incorrect":[{"choice":"Rachel mother said you have to take out the trash.","category":"missing punctuation","reason":"This sentence lacks both quotation marks to show spoken words and a comma to set off the person being addressed, making it difficult to tell who is speaking."},{"choice":"“Rachel, Mother said you have to take out the trash.”","category":"incorrect quotation scope","reason":"This choice incorrectly puts the entire sentence inside quotation marks, implying that Rachel is speaking the whole thing, rather than Mother speaking to Rachel."},{"choice":"Rachel Mother said, “You have to take out the trash.”","category":"missing direct address comma","reason":"This sentence is missing a comma after 'Rachel'. When you address someone by name directly, you must use a comma to separate their name from the rest of the sentence."},""]},"studyAid":{"definition":"Use quotation marks to surround the exact words someone says, and use a comma to separate the name of the person you are talking to from the rest of your sentence.","example":"\"John, please sit down,\" said the teacher. \"I am tired,\" said Sam.","strategyClue":"Look for the person being spoken to and identify which words are actually being spoken aloud. Ensure the name being addressed is separated by a comma and the spoken words are wrapped in quotation marks.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":70,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sourceFile":"Language Usage_Advanced 1_4th grade.pdf","sourceQuestionNumber":29,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":131,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-quotation-marks-q0209","version":3,"contentHash":"sha256:665463c344c4c2ec05360a0f49d0bcc7012dc07cfe0d85686798a7cb3f47f841","question":"Choose the line that has a punctuation error. If there is no error, choose “No mistakes.”","choices":["Where would you like to gofor dinner","My favorite food is either","Mexican food or Italian food.","No mistakes"],"correct":0,"explanation":{"correct":"Answer: Where would you like to gofor dinner. This sentence is missing a question mark at the end to show it is an inquiry, and the words 'go' and 'for' are incorrectly joined together without a space.","incorrect":["",{"choice":"My favorite food is either","category":"correct sentence fragment","reason":"This phrase is grammatically sound and contains no punctuation errors. It correctly introduces a choice using the word 'either'."},{"choice":"Mexican food or Italian food.","category":"correct sentence fragment","reason":"This phrase uses a period correctly to end the statement and provides a clear list of options."},{"choice":"No mistakes","category":"overlooked punctuation error","reason":"There is a clear error in the sentence about dinner; look closely at how the words are spaced and whether the sentence type requires an ending mark."}]},"studyAid":{"definition":"Every sentence should end with a mark such as a period, question mark, or exclamation point, and all separate words must have spaces between them.","example":"Correct: Where are you going? Incorrect: Where are you going (missing mark); Ilike cake (missing space).","strategyClue":"Read each line aloud and check for two things: does every word have a space around it, and does the sentence end with the correct punctuation for its purpose?","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sourceFile":"Language Usage_Basic 1_4th grade.pdf","sourceQuestionNumber":5,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":209,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}},{"id":"punctuation-quotation-marks-q0218","version":3,"contentHash":"sha256:808c1913a7964338cea9ba280ca9266f35ba3ed64d22d5837a71a1fa40541986","question":"Which sentence uses commas and quotation marks correctly?","choices":["Maria asked, “How many will be coming for dinner”?","Maria asked “How many will be coming for dinner?”","“Maria,” asked “How many will be coming for dinner?”","Maria asked, “How many will be coming for dinner?”"],"correct":3,"explanation":{"correct":"Answer: Maria asked, “How many will be coming for dinner?”. When a speaker asks a question, the question mark goes inside the closing quotation mark, and a comma is placed after the dialogue tag that introduces the speech.","incorrect":[{"choice":"Maria asked, “How many will be coming for dinner”?","category":"misplaced punctuation","reason":"The question mark belongs inside the quotation marks because it is part of what the person is actually saying. Moving it outside is incorrect."},{"choice":"Maria asked “How many will be coming for dinner?”","category":"missing comma","reason":"A comma is required to separate the speaker (Maria) and the verb (asked) from the actual words being spoken. You need that comma to introduce the quote clearly."},{"choice":"“Maria,” asked “How many will be coming for dinner?”","category":"incorrect quotation placement","reason":"The quotation marks should only surround the words spoken by Maria. Placing them around the speaker's name or splitting them this way confuses the reader about who said what."},""]},"studyAid":{"definition":"Dialogue requires a comma after the speaker tag and quotation marks around the spoken words, with terminal punctuation placed inside the closing quotation mark.","example":"He asked, “Where is my book?” / “I am hungry,” said Sam.","strategyClue":"Identify the exact words that were spoken out loud, then look for where the comma belongs before that set of words starts. Check that all end marks belonging to the speaker's words are safely tucked inside the quotation marks.","link":"https://www.readingrockets.org/topics/writing/articles/grammar-punctuation-and-spelling","linkText":"Reading Rockets - Grammar, Punctuation, and Spelling"},"metadata":{"gradeLevels":[4],"difficultyByGrade":{"4":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["punctuation","language usage","language","grade 4"],"feedbackFocus":"use the language rule, word clue, or sentence context to compare each answer choice","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"punctuation-quotation-marks","sourceFile":"Language Usage_Basic 1_4th grade.pdf","sourceQuestionNumber":14,"sourceCategory":"language-usage-test","sourceGrade":4,"testFocus":["MAP"],"Test focus":["MAP"],"sequence":218,"skillIds":["punctuation.conventions"],"standardIds":["L.3-6.2"]}}],"metadata":{"gradesSupported":[3,4,5,6],"difficultiesSupported":["easy","medium","hard"],"selectorPolicy":"grade+difficulty selects exact matches first, then nearby grade-appropriate practice to fill the configured mission length"}}}
  );
})();
